export type MicroVmResult = { code: number; stdout: string; stderr: string; timedOut: boolean };

export interface MicroVmClient {
  create(): Promise<{ id: string }>;
  exec(id: string, cmd: string[], timeoutMs: number): Promise<{ code: number; stdout: string; stderr: string }>;
  write(id: string, path: string, content: string): Promise<void>;
  stop(id: string): Promise<void>;
}

const TIMED_OUT = Symbol("timed-out");

function assertHttps(repoUrl: string): void {
  let url: URL;
  try {
    url = new URL(repoUrl);
  } catch {
    throw new Error(`repoUrl is not a valid URL: ${repoUrl}`);
  }
  if (url.protocol !== "https:") throw new Error(`repoUrl must be https: ${repoUrl}`);
}

export async function runInMicroVm(
  opts: { repoUrl: string; command: string[]; timeoutMs: number; files?: Record<string, string> },
  client: MicroVmClient,
): Promise<MicroVmResult> {
  assertHttps(opts.repoUrl);

  const deadline = Date.now() + opts.timeoutMs;
  const timeoutResult: MicroVmResult = { code: 124, stdout: "", stderr: "timeout", timedOut: true };
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<typeof TIMED_OUT>((resolve) => {
    timer = setTimeout(() => resolve(TIMED_OUT), opts.timeoutMs);
  });
  const step = <T>(p: Promise<T>) => Promise.race([p, timeout]);
  const remaining = () => Math.max(1, deadline - Date.now());

  let id: string | undefined;
  let result: MicroVmResult | undefined;
  let failure: { error: unknown } | undefined;
  try {
    const created = await step(client.create());
    if (created === TIMED_OUT) return timeoutResult;
    id = created.id;

    for (const [path, content] of Object.entries(opts.files ?? {})) {
      const w = await step(client.write(id, path, content));
      if (w === TIMED_OUT) return (result = timeoutResult);
    }

    const clone = await step(
      client.exec(id, ["git", "clone", "--filter=blob:none", opts.repoUrl, "/work"], remaining()),
    );
    if (clone === TIMED_OUT) return (result = timeoutResult);
    if (clone.code === 124) return (result = { ...clone, timedOut: true });
    if (clone.code !== 0) return (result = { ...clone, timedOut: false });

    const run = await step(
      client.exec(id, ["sh", "-c", 'cd /work && exec "$@"', "sh", ...opts.command], remaining()),
    );
    if (run === TIMED_OUT) return (result = timeoutResult);
    return (result = { ...run, timedOut: run.code === 124 });
  } catch (error) {
    failure = { error };
    throw error;
  } finally {
    clearTimeout(timer);
    if (id !== undefined) {
      try {
        await client.stop(id);
      } catch (stopError) {
        // Don't mask an earlier failure; otherwise surface the leaked VM.
        if (!failure) throw stopError;
      }
    }
  }
}
EOF
cat > tests/microvm.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { runInMicroVm, type MicroVmClient } from "../src/sandbox/microvm";

function fake(over: Partial<MicroVmClient> = {}) {
  const calls: string[] = [];
  const client: MicroVmClient = {
    create: async () => (calls.push("create"), { id: "vm1" }),
    write: async (_id, p) => void calls.push(`write:${p}`),
    exec: async (_id, cmd) => (calls.push(`exec:${cmd.join(" ")}`), { code: 0, stdout: "ok", stderr: "" }),
    stop: async () => void calls.push("stop"),
    ...over,
  };
  return { client, calls };
}
const base = { repoUrl: "https://github.com/a/b", command: ["bun", "test"], timeoutMs: 1000 };

describe("runInMicroVm", () => {
  test("create, write, clone, command, stop in order", async () => {
    const { client, calls } = fake();
    const r = await runInMicroVm({ ...base, files: { "/work/x": "y" } }, client);
    expect(r).toEqual({ code: 0, stdout: "ok", stderr: "", timedOut: false });
    expect(calls[0]).toBe("create");
    expect(calls[1]).toBe("write:/work/x");
    expect(calls[2]).toBe("exec:git clone --filter=blob:none https://github.com/a/b /work");
    expect(calls[3]).toContain("cd /work");
    expect(calls[3]).toContain("bun test");
    expect(calls[4]).toBe("stop");
  });

  test("rejects non-https before creating", async () => {
    for (const u of ["http://x.com/a", "[REDACTED_EMAIL]:a/b.git", "file:///tmp/r", "ssh://x/y"]) {
      const { client, calls } = fake();
      await expect(runInMicroVm({ ...base, repoUrl: u }, client)).rejects.toThrow();
      expect(calls).toEqual([]);
    }
  });

  test("timeout returns 124 and still stops", async () => {
    const { client, calls } = fake({ exec: () => new Promise(() => {}) });
    const r = await runInMicroVm({ ...base, timeoutMs: 30 }, client);
    expect(r.timedOut).toBe(true);
    expect(r.code).toBe(124);
    expect(calls.at(-1)).toBe("stop");
  });

  test("stops after exec error", async () => {
    const { client, calls } = fake({ exec: async () => { throw new Error("boom"); } });
    await expect(runInMicroVm(base, client)).rejects.toThrow("boom");
    expect(calls.at(-1)).toBe("stop");
  });

  test("failed clone skips command and stops", async () => {
    const { client, calls } = fake({ exec: async (_i, c) => (calls.push(`exec:${c[0]}`), { code: 128, stdout: "", stderr: "nope" }) });
    const r = await runInMicroVm(base, client);
    expect(r.code).toBe(128);
    expect(calls.filter((c) => c.startsWith("exec")).length).toBe(1);
    expect(calls.at(-1)).toBe("stop");
  });

  test("stop is called when write fails", async () => {
    const { client, calls } = fake({ write: async () => { throw new Error("w"); } });
    await expect(runInMicroVm({ ...base, files: { a: "b" } }, client)).rejects.toThrow("w");
    expect(calls).toEqual(["create", "stop"]);
  });

  test("no stop when create fails", async () => {
    const { client, calls } = fake({ create: async () => { throw new Error("c"); } });
    await expect(runInMicroVm(base, client)).rejects.toThrow("c");
    expect(calls).toEqual([]);
  });
});
EOF
