export type MicroVmResult = { code: number; stdout: string; stderr: string; timedOut: boolean };

export interface MicroVmClient {
  create(): Promise<{ id: string }>;
  exec(id: string, cmd: string[], timeoutMs: number): Promise<{ code: number; stdout: string; stderr: string }>;
  write(id: string, path: string, content: string): Promise<void>;
  stop(id: string): Promise<void>;
}

const TIMED_OUT = Symbol("timed-out");

function assertHttps(repoUrl: string): void {
  let url: URL;
  try {
    url = new URL(repoUrl);
  } catch {
    throw new Error(`repoUrl is not a valid URL: ${repoUrl}`);
  }
  if (url.protocol !== "https:") throw new Error(`repoUrl must be https: ${repoUrl}`);
}

export async function runInMicroVm(
  opts: { repoUrl: string; command: string[]; timeoutMs: number; files?: Record<string, string> },
  client: MicroVmClient,
): Promise<MicroVmResult> {
  assertHttps(opts.repoUrl);

  const deadline = Date.now() + opts.timeoutMs;
  const timeoutResult: MicroVmResult = { code: 124, stdout: "", stderr: "timeout", timedOut: true };
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<typeof TIMED_OUT>((resolve) => {
    timer = setTimeout(() => resolve(TIMED_OUT), opts.timeoutMs);
  });
  const step = <T>(p: Promise<T>) => Promise.race([p, timeout]);
  const remaining = () => Math.max(1, deadline - Date.now());

  let id: string | undefined;
  let failed = false;
  try {
    const created = await step(client.create());
    if (created === TIMED_OUT) return timeoutResult;
    id = created.id;

    for (const [path, content] of Object.entries(opts.files ?? {})) {
      if ((await step(client.write(id, path, content))) === TIMED_OUT) return timeoutResult;
    }

    const clone = await step(
      client.exec(id, ["git", "clone", "--filter=blob:none", opts.repoUrl, "/work"], remaining()),
    );
    if (clone === TIMED_OUT) return timeoutResult;
    if (clone.code !== 0) return { ...clone, timedOut: clone.code === 124 };

    const run = await step(
      client.exec(id, ["sh", "-c", 'cd /work && exec "$@"', "sh", ...opts.command], remaining()),
    );
    if (run === TIMED_OUT) return timeoutResult;
    return { ...run, timedOut: run.code === 124 };
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    clearTimeout(timer);
    // If create itself timed out, its VM id is unknown and cannot be stopped here.
    if (id !== undefined) {
      try {
        await client.stop(id);
      } catch (stopError) {
        // Don't mask an earlier failure; otherwise surface the leaked VM.
        if (!failed) throw stopError;
      }
    }
  }
}

